func settler25() *Pix {
	p := NewPix(len(settler25Rows[0]), len(settler25Rows), settler25Pal)
	for y, row := range settler25Rows {
		for x, r := range row {
			var i int
			if r >= '0' && r <= '9' {
				i = int(r - '0')
			} else {
				i = int(r-'a') + 10
			}
			p.Set(x, y, uint8(i))
		}
	}
