}

// TestSettler25 is the finding measured on real art rather than on a fixture
// chosen to show it.
//
// Settler #25 carries 20 palette entries. Keyed on the palette index, all 20
// survive into the text. Keyed on luminance, a ten-step ramp resolves them to
// 9: eleven of the artist's twenty colours stop existing, and the shapes
// between them go with it.
//
// That is the whole argument for Glyphs being the default and Ramp being the
// thing you ask for.
func TestSettler25PaletteBeatsLuminance(t *testing.T) {
	glyphs := settler25().Canvas(Glyphs).Text()
	ramp := settler25().Canvas(Ramp).Text()

	// distinctRunes counts the newline too, so both figures are colours + 1.
	uassert.Equal(t, 21, distinctRunes(glyphs), "every palette entry survives")
	uassert.Equal(t, 10, distinctRunes(ramp), "the ramp resolves 20 colours to 9")
	uassert.True(t, distinctRunes(glyphs) > distinctRunes(ramp), "glyphs strictly finer")
}

// TestSettler25SVGIsOnePathPerColour pins the encoding that keeps a sprite
// small enough for a realm to emit. 20 colours, 20 paths, and 4,532 bytes where
// one rectangle per run cost 20,625.
func TestSettler25SVGIsOnePathPerColour(t *testing.T) {
	doc := settler25().SVG(8).String()
	uassert.Equal(t, 20, strings.Count(doc, "<path"), "one path per palette entry")
	uassert.Equal(t, 0, strings.Count(doc, "<rect"), "no rectangles at all")
	uassert.True(t, len(doc) < 6000, "a 32x32 sprite stays well under 6 KB")
	// Scaling is a viewBox change, so the path data, which is all of the size,
	// is byte-identical at any scale. Only the canvas width and height move,
	// and here that is one digit each between "32" and "256".
	one := settler25().SVG(1).String()
	uassert.Equal(t, paths(one), paths(doc), "path data is identical at any scale")
	uassert.Equal(t, 2, len(doc)-len(one), "only the canvas dimensions grow")
}

// paths returns the document from its first <path> on, which is everything
// scale cannot affect.
func paths(doc string) string {
	i := strings.Index(doc, "<path")
	if i < 0 {
		return ""
	}
	return doc[i:]
}

// TestSettler25TextIsSmallerThanItsPicture is the reason a text target is worth
// having at all, beyond readability: the ASCII form of this NFT is a third of
// the SVG.
func TestSettler25TextIsSmallerThanItsPicture(t *testing.T) {
	text := settler25().Canvas(Glyphs).Text()
	uassert.Equal(t, 1469, len(text), "glyph text size")
	uassert.True(t, len(text) < len(settler25().SVG(8).String()), "text is the cheaper form")
}

// TestSettler25RampConfusesHueForBrightness is the part of the finding that is
// easy to miss: the ramp's collisions are not between near-identical shades.
// Two colours a human would never confuse, an orange hat and a sky-blue tunic,
// come out as the same character, because luminance cannot tell a hue from a
// hue.
func TestSettler25RampConfusesHueForBrightness(t *testing.T) {
	orange := settler25Pal.Color(4) // #f08a2a, the hat
	blue := settler25Pal.Color(16)  // #3f8fd1, the tunic

	uassert.Equal(t, 152, Luminance(orange), "orange hat")
	uassert.Equal(t, 130, Luminance(blue), "sky tunic")
	uassert.NotEqual(t, orange, blue, "they are different colours")
	uassert.Equal(t, rampGlyph(orange), rampGlyph(blue), "and the same ramp glyph")

	// Keyed on the palette index instead, they cannot collide: the indices are
	// different, so the glyphs are.
	uassert.NotEqual(t,
		DefaultGlyphs[4%len(DefaultGlyphs)],
		DefaultGlyphs[16%len(DefaultGlyphs)],
		"glyphs keep them apart")
}

func rampGlyph(c int) rune {
	return DefaultRamp[Luminance(c)*len(DefaultRamp)/256]
}

package art

import (
	"strings"

	"gno.land/p/moul/svg/v0"
)

// SVGOpts configures [Canvas.SVG]. The zero value is usable: every field falls
// back to the constant beside it.
type SVGOpts struct {
	CellW, CellH int    // cell size in SVG units; 0 means 8 and 16
	FG, BG       int    // what a cell's Default resolves to; Default stays unset
	Font         string // font-family; "" means a monospace stack
}

// Defaults for [SVGOpts]. 8x16 is the usual terminal cell ratio, so art laid
// out for a terminal keeps its proportions.
const (
	DefaultCellW = 8
	DefaultCellH = 16
	DefaultFont  = "ui-monospace,SFMono-Regular,Menlo,Consolas,monospace"
)

// SVG renders the canvas as an SVG document: background colours as run-length
// rectangles, and one <text> element per non-blank cell, centred in its cell so
// the grid stays aligned whatever the renderer's idea of a monospace advance
// width is.
//
// This is how colour reaches gnoweb. [Canvas.ANSI] cannot: raw ESC bytes are
// stripped by p/nt/markdown/sanitize and are garbage in HTML regardless. An
// SVG carries the same two colours per cell through a medium the web can show,
// which is the whole argument for making the target a parameter.
//
// One element per cell rather than one per run is deliberate: a run of text
// would have to assume the font's advance width, and a renderer that disagreed
// would shear the picture. Dense pixel art should go through [Pix.SVG] instead,
// which is run-length and has no font to get wrong.
func (c Canvas) SVG(o SVGOpts) *svg.Canvas {
	cw, ch := o.CellW, o.CellH
	if cw <= 0 {
		cw = DefaultCellW
	}
	if ch <= 0 {
		ch = DefaultCellH
	}
	font := o.Font
	if font == "" {
		font = DefaultFont
	}

	out := svg.NewCanvas(c.W*cw, c.H*ch)
	out.WithViewBox(0, 0, c.W*cw, c.H*ch)
	out.AddStyle("text", "font-family:"+font+";font-size:"+itoa(ch)+"px;text-anchor:middle;dominant-baseline:central")
	out.AddStyle("rect", "shape-rendering:crispEdges")

	// Backgrounds first, as horizontal runs, so they sit under the glyphs.
	for y := 0; y < c.H; y++ {
		x := 0
		for x < c.W {
			bg := c.bgAt(x, y, o.BG)
			run := 1
			for x+run < c.W && c.bgAt(x+run, y, o.BG) == bg {
				run++
			}
			if bg != Default {
				out.Append(svg.NewRectangle(x*cw, y*ch, run*cw, ch, Hex(bg)))
			}
			x += run
		}
	}

	for y := 0; y < c.H; y++ {
		for x := 0; x < c.W; x++ {
			cell := c.Cells[y*c.W+x]
			if cell.R == ' ' || cell.R == 0 {
				continue
			}
			fg := cell.FG
			if fg == Default {
				fg = o.FG
			}
			fill := Hex(fg)
			if fill == "" {
				fill = "currentColor"
			}
			out.Append(svg.NewText(x*cw+cw/2, y*ch+ch/2, escapeXML(string(cell.R)), fill))
		}
	}
	return out
}

func (c Canvas) bgAt(x, y, fallback int) int {
	bg := c.Cells[y*c.W+x].BG
	if bg == Default {
		return fallback
	}
	return bg
}

// escapeXML is here and not in p/moul/svg because svg.Text interpolates its
// content straight into the document: a rune this package can legitimately
// produce, or a title a caller typed, would otherwise close the element.
func escapeXML(s string) string {
	if !strings.ContainsAny(s, "&<>\"") {
		return s
	}
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var buf [20]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

package gallery

import (
	"gno.land/r/moul/demo/gnoface/v0"
	"gno.land/r/moul/demo/millipede/v0"
	"gno.land/r/moul/sapin/v0"
)

// piece is one entry in the index.
//
// The gallery stores no art. Every piece lives in somebody's realm and this is
// a pointer to it, which is why there is no package-level state anywhere in
// this realm and nothing here survives or needs to survive a redeploy.
type piece struct {
	Slug    string
	Title   string
	Author  string
	Origin  string // realm path, without the gno.land prefix
	License string
	Note    string

	// Draw renders the piece live, by importing its source. It is nil when the
	// source cannot be imported, which is the honest half of a curated index:
	// a private realm or a package this repo has not vendored can be pointed
	// at but not shown.
	Draw func() string
}

// Live reports whether this realm can render the piece itself.
func (p piece) Live() bool { return p.Draw != nil }

// catalog is built per call rather than held in a package-level var: a func
// value is not something to persist, and a realm that stores nothing should
// not be paying storage for its own index.
func catalog() []piece {
	return []piece{
		{
			Slug:    "gnoface",
			Title:   "gnoface",
			Author:  "moul",
			Origin:  "r/moul/demo/gnoface/v0",
			License: "see the source realm",
			Note:    "A face generated from a seed. Every seed is a different face, and none of them are stored.",
			Draw:    func() string { return gnoface.Draw(42) },
		},
		{
			Slug:    "millipede",
			Title:   "millipede",
			Author:  "moul",
			Origin:  "r/moul/demo/millipede/v0",
			License: "see the source realm",
			Note:    "A millipede of any length. The oldest piece here, and still the one that best explains why ASCII is the cheapest picture there is.",
			Draw:    func() string { return millipede.Draw(8) },
		},
		{
			Slug:    "sapin",
			Title:   "sapin",
			Author:  "moul",
			Origin:  "r/moul/sapin/v0",
			License: "see the source realm",
			Note:    "A fir tree, sized on request.",
			Draw:    func() string { return sapin.Sapin(6) },
		},
		{
			Slug:    "settler25",
			Title:   "Settler #25",
			Author:  "the Settlers",
			Origin:  "r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft",
			License: "CC0 1.0",
			Note:    "moul's, soulbound, minted at block 409242. A 32x32 indexed sprite with 20 colours, which is what made it the test case for p/moul/art: a luminance ramp resolves those 20 to 9, and keying on the palette index keeps all 20.",
		},
		{
			Slug:    "asciiart",
			Title:   "asciiart",
			Author:  "moul",
			Origin:  "r/moul/x/daily/asciiart/v1",
			License: "see the source realm",
			Note:    "Patterns from short deterministic algorithms, plus everyone's generations. Declared private = true, so it can be linked but never imported: that is the constraint, not an omission.",
		},
		{
			Slug:    "pixelcanvas",
			Title:   "pixelcanvas",
			Author:  "moul",
			Origin:  "r/moul/x/daily/pixelcanvas/v0",
			License: "see the source realm",
			Note:    "A shared grid anyone can paint one pixel of.",
		},
	}
}

func find(slug string) (piece, bool) {
	for _, p := range catalog() {
		if p.Slug == slug {
			return p, true
		}
	}
	return piece{}, false
}

// Package gallery is a curated index of art on gno.land, in whichever form the
// reader can actually consume.
//
// It stores no art. Every piece lives in somebody else's realm; this one
// renders the ones it can import and points at the ones it cannot.
//
// # The target is a parameter
//
// Every page answers to ?fmt=txt as well as the default markdown. The text
// target is not markdown with the characters deleted: links become numbered
// footnotes, headings get underlines instead of a leading '#', and art is
// emitted verbatim rather than fenced. The result is meant to be piped, or read
// by anything that is not a browser.
//
// ?fmt=ansi is deliberately absent. Colour cannot reach gnoweb, so a realm that
// offered it would be handing every web reader a page of escape bytes. Terminal
// colour is p/moul/art's Canvas.ANSI, for a consumer that asked for it over
// something other than gnoweb.
package gallery

import (
	"strings"

	"gno.land/p/moul/art/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/realmpath/v0"
)

// realmPath is this realm's own path, version included.
//
// gnoweb does NOT resolve an unversioned realm path to its latest version: it
// serves /r/moul/gallery as a DIRECTORY INDEX and drops the :path and ?query
// entirely. Measured 2026-09-30 on gnoland-1, where /r/moul/outfmt:?fmt=json
// renders the index page while /r/moul/outfmt/v0:?fmt=json returns the JSON.
// So every self-link has to carry the version, and stating it once is what
// keeps the next one from being written without it. Only r/moul/home and
// r/moul/blog are genuinely unversioned paths.
const realmPath = "/r/moul/gallery/v0"

func Render(path string) string {
	req := realmpath.Parse(path)
	text := req.Query.Get("fmt") == "txt"

	if slug := strings.TrimPrefix(req.Path, "piece/"); slug != req.Path && slug != "" {
		return renderPiece(slug, text)
	}
	return renderIndex(text)
}

// banner is drawn with p/moul/art rather than typed as a string literal,
// because a gallery that hand-writes its own ASCII would be a poor advert for
// the library it exists to show.
func banner() string {
	c := art.NewCanvas(22, 2)
	c.Write(0, 0, "moul's gallery")
	c.Write(0, 1, "art on gno.land")
	return c.Frame("", art.Round).Text()
}

func renderIndex(text bool) string {
	live, linked := 0, 0
	for _, p := range catalog() {
		if p.Live() {
			live++
		} else {
			linked++
		}
	}

	if text {
		var d doc
		d.Art(banner())
		d.Para("Art on gno.land, rendered rather than described. Nothing here is stored in this realm: every piece lives where its author put it.")
		rows := [][]string{}
		for _, p := range catalog() {
			shown := "linked"
			if p.Live() {
				shown = "rendered here"
			}
			rows = append(rows, []string{p.Slug, p.Author, p.Origin, shown})
		}
		d.Table([]string{"Piece", "Author", "Where", "Shown"}, rows)
		d.Para(plural(live, "piece") + " rendered from source, " + plural(linked, "piece") + " linked.")
		d.Para("Open one at " + realmPath + ":piece/<slug>, with ?fmt=txt for this form.")
		return d.String()
	}

	out := md.H1("moul's gallery")
	out += md.CodeBlock(banner())
	out += "\n"
	out += "Art on gno.land, rendered rather than described. Nothing here is stored in this realm: every piece lives where its author put it.\n\n"

	t := ui.NewTable("Piece", "Author", "Where", "Shown")
	for _, p := range catalog() {
		shown := "linked"
		if p.Live() {
			shown = "rendered here"
		}
		t.Row(
			md.Link(p.Title, realmPath+":piece/"+p.Slug),
			ui.Inline(p.Author),
			md.InlineCode(p.Origin),
			shown,
		)
	}
	out += t.OrEmpty("nothing indexed yet")
	out += "\n" + md.Italic(plural(live, "piece")+" rendered from source, "+plural(linked, "piece")+" linked.") + "\n\n"
	out += md.Italic("Every page here also answers to `?fmt=txt`.") + "\n"
	return out
}

func renderPiece(slug string, text bool) string {
	p, ok := find(slug)
	if !ok {
		if text {
			return "No piece called " + slug + ".\n"
		}
		return md.H1("Not found") + ui.Empty("no piece called "+ui.Inline(slug))
	}

	if text {
		var d doc
		d.H1(p.Title)
		if p.Live() {
			d.Art(p.Draw())
		} else {
			d.Para("Not rendered here: this realm cannot import the source.")
		}
		d.Para(p.Note)
		d.Field("Author", p.Author)
		d.Field("License", p.License)
		d.Field("Source", p.Origin)
		d.Link("the source realm", "https://gno.land/"+p.Origin)
		return d.String()
	}

	out := md.H1(p.Title)
	if p.Live() {
		out += md.CodeBlock(p.Draw())
	} else {
		out += ui.Empty("not rendered here: this realm cannot import the source") + "\n"
	}
	out += "\n" + ui.Inline(p.Note) + "\n\n"

	t := ui.NewTable("Field", "Value")
	t.Row("Author", ui.Cell(p.Author))
	t.Row("License", ui.Cell(p.License))
	t.Row("Source", md.Link(p.Origin, "/"+p.Origin))
	out += t.String()

	out += "\n" + md.Link("< the gallery", realmPath) + "\n"
	return out
}

func plural(n int, word string) string {
	s := itoa(n) + " " + word
	if n != 1 {
		s += "s"
	}
	return s
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	return string(buf[i:])
}

package gallery

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestRenderIndexMarkdown(t *testing.T) {
	out := Render("")
	uassert.True(t, strings.Contains(out, "# moul's gallery"), "heading")
	uassert.True(t, strings.Contains(out, "```"), "the banner is fenced in markdown")
	uassert.True(t, strings.Contains(out, "| Piece |"), "a real markdown table")
	// The path is spelled out rather than taken from realmPath: a test that
	// reads the same constant the code does would pass with the version
	// dropped, which is the exact regression this pins.
	for _, p := range catalog() {
		uassert.True(t, strings.Contains(out, "/r/moul/gallery/v0:piece/"+p.Slug), p.Slug+" is linked")
	}
}

// The two targets are different documents, not one with characters deleted.
func TestTextTargetStripsMarkdownAndDefersLinks(t *testing.T) {
	out := Render("piece/millipede?fmt=txt")

	uassert.False(t, strings.Contains(out, "```"), "no code fences")
	uassert.False(t, strings.Contains(out, "**"), "no bold markers")
	uassert.False(t, strings.Contains(out, "]("), "no inline link syntax")
	uassert.False(t, strings.Contains(out, "\n#"), "no heading hashes")

	// A heading is underlined instead.
	uassert.True(t, strings.Contains(out, "millipede\n========="), "underlined heading")
	// And the URL is a numbered footnote, not inline noise.
	uassert.True(t, strings.Contains(out, "the source realm [1]"), "inline marker")
	uassert.True(t, strings.Contains(out, "\nLinks:\n  [1] https://gno.land/r/moul/demo/millipede/v0"), "footnote block")
}

func TestTextTableColumnsLineUp(t *testing.T) {
	out := Render("?fmt=txt")
	var header, rule string
	for _, line := range strings.Split(out, "\n") {
		if strings.HasPrefix(line, "  Piece ") {
			header = line
		}
		if strings.HasPrefix(line, "  ---") {
			rule = line
		}
	}
	uassert.True(t, header != "", "found the header")
	uassert.True(t, rule != "", "found the rule")

	// Every column boundary in the rule is a pair of spaces in the header at
	// the same rune offset. That is the property an unpadded pipe table does
	// not have, and the reason the text target has its own table at all.
	uassert.Equal(t, gutters(rule), gutters(header), "columns start at the same offsets")
}

// gutters returns the rune offsets at which a column starts: a non-space
// preceded by at least two spaces. Measuring where the PADDING starts instead
// would compare "Piece" against eleven dashes and report a difference that is
// not one.
func gutters(s string) string {
	r := []rune(s)
	out := ""
	for i := 2; i < len(r); i++ {
		if r[i] != ' ' && r[i-1] == ' ' && r[i-2] == ' ' {
			out += itoa(i) + ","
		}
	}
	return out
}

func TestArtIsNeverEscapedOrWrapped(t *testing.T) {
	// The millipede is box-drawing and parentheses. A text target that ran it
	// through an escaper or a wrapper would ruin it, and it would still look
	// like a picture, which is what makes this worth pinning.
	out := Render("piece/millipede?fmt=txt")
	uassert.True(t, strings.Contains(out, "╚═(███)═╝"), "art survives verbatim")
	uassert.False(t, strings.Contains(out, "\\("), "no escaping")
}

func TestUnknownPiece(t *testing.T) {
	uassert.True(t, strings.Contains(Render("piece/nope"), "no piece called nope"), "markdown 404")
	uassert.True(t, strings.Contains(Render("piece/nope?fmt=txt"), "No piece called nope."), "text 404")
	// An empty slug is the index, not a 404.
	uassert.True(t, strings.Contains(Render("piece/"), "# moul's gallery"), "empty slug falls back to the index")
}

func TestLinkedPiecesSayWhyTheyAreNotRendered(t *testing.T) {
	p, ok := find("asciiart")
	uassert.True(t, ok, "found")
	uassert.False(t, p.Live(), "asciiart is private = true, so it cannot be imported")

	out := Render("piece/asciiart")
	uassert.True(t, strings.Contains(out, "cannot import the source"), "says so rather than showing nothing")
}

func TestEveryPieceRenders(t *testing.T) {
	for _, p := range catalog() {
		out := Render("piece/" + p.Slug)
		uassert.True(t, strings.Contains(out, p.Title), p.Slug+" markdown")
		uassert.True(t, len(Render("piece/"+p.Slug+"?fmt=txt")) > 0, p.Slug+" text")
	}
}

func TestWrapKeepsLongWordsIntact(t *testing.T) {
	long := "see gno.land/r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft now"
	got := wrap(long, 20)
	// A path is worse broken than wide, so it overflows rather than splitting.
	uassert.True(t, strings.Contains(got, "gno.land/r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft"), "unbroken")
	uassert.Equal(t, 3, len(strings.Split(got, "\n")), "three lines")
}

